parameters.jsCode:
const geminiRaw = $input.first().json;
let blueprint = {};
try {
  blueprint = JSON.parse(geminiRaw.candidates[0].content.parts[0].text);
} catch(e) {
  blueprint = {
    headline: 'Bespoke Architectural Living',
    caption: 'Transforming everyday spaces into timeless sanctuaries. Connect with our architects today.',
    fluxImagePrompt: 'minimalist luxury living room, floor-to-ceiling panoramic glass windows, warm golden hour ambient lighting, Italian marble flooring, 8k photography',
    klingVideoPrompt: 'smooth camera dolly forward into luxury living room, warm sunlight rays shifting across marble floor, 4k 60fps',
    voiceoverScript: 'Step into a world crafted purely for you. Where every detail inspires grandeur.'
  };
}

// Generate FLUX Image URL via high-speed API
const encodedImagePrompt = encodeURIComponent(blueprint.fluxImagePrompt);
const imageUrl = `https://image.pollinations.ai/prompt/${encodedImagePrompt}?width=1080&height=1350&model=flux&nologo=true&seed=${Math.floor(Math.random() * 999999)}`;

return [{
  json: {
    blueprint,
    imageUrl,
    clientName: $('Webhook On-Demand Trigger').first()?.json?.body?.clientName || 'Apex Luxe',
    clientEmail: $('Webhook On-Demand Trigger').first()?.json?.body?.clientEmail || 'client@synapsekinetic.ai',
    industry: $('Webhook On-Demand Trigger').first()?.json?.body?.industry || 'Interior Design'
  }
}];

const baseData = $('Step 3: FLUX.1 4K Image Render Generator').first().json;
const klingRes = $('Step 4: Kling AI Image-to-Video Reel Synthesizer').first()?.json || {};

// Final combined deliverable package
const videoUrl = klingRes.data?.video_url || 'https://assets.mixkit.co/videos/preview/mixkit-modern-apartment-with-panoramic-view-40742-large.mp4';

return [{
  json: {
    deliverableId: 'DELIV-' + Date.now().toString().slice(-6),
    clientName: baseData.clientName,
    clientEmail: baseData.clientEmail,
    industry: baseData.industry,
    headline: baseData.blueprint.headline,
    adCopy: baseData.blueprint.caption,
    imageUrl: baseData.imageUrl,
    videoUrl: videoUrl,
    voiceoverScript: baseData.blueprint.voiceoverScript,
    format: 'multimodal_bundle',
    status: 'pending_approval',
    generatedAt: new Date().toISOString(),
    approvalReviewUrl: 'http://localhost:3000/admin/clients'
  }
}];
